Rules.InvariantScript:
UpdateContext({var_load: true});
Switch(
    var_modulo,
    "Colisão de veículos",////////////////////////////////////////////////////////////////////////////////
    Remove(
        '14.4-tbl_ColVeiculos',
        var_item
    );
    RemoveIf(
        '14.4-tbl_ColVeiculosEnvolvidos',
        colVeiEnv_idOcorrencia = var_item.derFlu_id
    );
    RemoveIf(
        '14.4-tbl_ColVeiculosImg',
        colVeiImg_idOcorrencia = var_item.derFlu_id
    );
    RemoveIf(
        tbl_desdobramentos,
        Modulo = var_modulo And ID_ocorrencia = var_item.derFlu_id
    );
    If(
        IsBlank(
            LookUp(
                '14.4-tbl_ColVeiculos',
                ID = var_item.ID
            )
        ),
        Navigate(
            ScreenSucesso,
            ScreenTransition.Fade,
            {var_navigateSucess: ScreenColisaoVeiculos}
        ),
        Navigate(
            ScreenErro,
            ScreenTransition.Fade,
            {var_navigateErro: ScreenColisaoVeiculos}
        )
    ),
    "Derramamento de fluídos",///////////////////////////////////////////////////////////////////////////
    Remove(
        '14.2-tbl_DerramamentoDeFluidos',
        var_item
    );
    RemoveIf(
        '14.2-tbl_DerFluidosImg',
        derFluFK_id = var_item.ID
    );
    RemoveIf(
        tbl_desdobramentos,
        Modulo = var_modulo And ID_ocorrencia = var_item.ID
    );
    If(
        IsBlank(
            LookUp(
                '14.2-tbl_DerramamentoDeFluidos',
                ID = var_item.ID
            )
        ),
        Navigate(
            ScreenSucesso,
            ScreenTransition.Fade,
            {var_navigateSucess: ScreenDerramamentoFluido}
        ),
        Navigate(
            ScreenErro,
            ScreenTransition.Fade,
            {var_navigateErro: ScreenDerramamentoFluido}
        )
    ),
    "Excursão de pista",/////////////////////////////////////////////////////////////////////////////////
    Remove(
        '14.6-tbl_ExcPista',
        var_item
    );
    RemoveIf(
        '14.6-tbl_ExcPistaImg',
        excPistaImg_idOcorrencia = var_item.ID
    );
    RemoveIf(
        tbl_desdobramentos,
        Modulo = var_modulo And ID_ocorrencia = var_item.ID
    );
    If(
        IsBlank(
            LookUp(
                '14.6-tbl_ExcPista',
                ID = var_item.ID
            )
        ),
        Navigate(
            ScreenSucesso,
            ScreenTransition.Fade,
            {var_navigateSucess: ScreenExcursaoPista}
        ),
        Navigate(
            ScreenErro,
            ScreenTransition.Fade,
            {var_navigateErro: ScreenExcursaoPista}
        )
    ),
    "Incursão em pista",/////////////////////////////////////////////////////////////////////////////////
    Remove(
        '14.3-tbl_IncPista',
        var_item
    );
    RemoveIf(
        '14.3-tbl_IncPistaImg',
        incPistaImg_idOcorrencia = var_item.ID
    );
    RemoveIf(
        '14.3-tbl_IncPistaEnvolvidos',
        incPistaEnv_idOcorrencia = var_item.ID
    );
    RemoveIf(
        tbl_desdobramentos,
        Modulo = var_modulo And ID_ocorrencia = var_item.ID
    );
    If(
        IsBlank(
            LookUp(
                '14.3-tbl_IncPista',
                ID = var_item.ID
            )
        ),
        Navigate(
            ScreenSucesso,
            ScreenTransition.Fade,
            {var_navigateSucess: ScreenIncursaoPista}
        ),
        Navigate(
            ScreenErro,
            ScreenTransition.Fade,
            {var_navigateErro: ScreenIncursaoPista}
        )
    ),
    "Interferência externa",/////////////////////////////////////////////////////////////////////////////////
    Remove(
        '14.5-tbl_IntExterna',
        var_item
    );
    RemoveIf(
        '14.5-tbl_IntExternaImg',
        intExtImg_idOcorrencia = var_item.ID
    );
    RemoveIf(
        tbl_desdobramentos,
        Modulo = var_modulo And ID_ocorrencia = var_item.ID
    );
    If(
        IsBlank(
            LookUp(
                '14.5-tbl_IntExterna',
                ID = var_item.ID
            )
        ),
        Navigate(
            ScreenSucesso,
            ScreenTransition.Fade,
            {var_navigateSucess: ScreenInterferenciaExterna}
        ),
        Navigate(
            ScreenErro,
            ScreenTransition.Fade,
            {var_navigateErro: ScreenInterferenciaExterna}
        )
    ),
    "Jet blast",/////////////////////////////////////////////////////////////////////////////////
    Remove(
        '14.8-tbl_JetBlast',
        var_item
    );
    RemoveIf(
        '14.8-tbl_JetBlastImg',
        jetBlastImg_idOcorrencia = var_item.ID
    );
    RemoveIf(
        '14.8-tbl_JetBlastItemAtingido',
        jetBlastIA_idOcorrencia = var_item.ID
    );
    RemoveIf(
        tbl_desdobramentos,
        Modulo = var_modulo And ID_ocorrencia = var_item.ID
    );
    If(
        IsBlank(
            LookUp(
                '14.8-tbl_JetBlast',
                ID = var_item.ID
            )
        ),
        Navigate(
            ScreenSucesso,
            ScreenTransition.Fade,
            {var_navigateSucess: ScreenJetBlast}
        ),
        Navigate(
            ScreenErro,
            ScreenTransition.Fade,
            {var_navigateErro: ScreenJetBlast}
        )
    ),
    "Ocorrência de solo",/////////////////////////////////////////////////////////////////////////////////////
    Remove(
        '16.1-tbl_OcoSolo',
        var_item
    );
    RemoveIf(
        '16.1-tbl_OcoSoloImagens',
        ocoSoloFK_id = var_item.ID
    );
    RemoveIf(
        tbl_desdobramentos,
        Modulo = var_modulo And ID_ocorrencia = var_item.ID
    );
    If(
        IsBlank(
            LookUp(
                '16.1-tbl_OcoSolo',
                ID = var_item.ID
            )
        ),
        Navigate(
            ScreenSucesso,
            ScreenTransition.Fade,
            {var_navigateSucess: ScreenOcorrenciaSolo}
        ),
        Navigate(
            ScreenErro,
            ScreenTransition.Fade,
            {var_navigateErro: ScreenOcorrenciaSolo}
        )
    ),
    "Fauna",/////////////////////////////////////////////////////////////////////////////////////
    Switch(
        var_faunaCat,
        "Colisão",
        RemoveIf(
            'AIRPORTNOW - FAUNA RELACIONAMENTO',
            ID_tblPrincipal = var_item.ID And 'Tipo de Registro' = "Colisão com dano" || ID_tblPrincipal = var_item.ID And 'Tipo de Registro' = "Colisão sem dano" || ID_tblPrincipal = var_item.ID And 'Tipo de Registro' = "Quase colisão" || ID_tblPrincipal = var_item.ID And 'Tipo de Registro' = "Avistamento"
        );
        RemoveIf(
            'AIRPORTNOW - Colisões/Quase-Colisão/Avistamento',
            ID = var_item.ID
        );
        If(
            IsBlank(
                LookUp(
                    'AIRPORTNOW - Colisões/Quase-Colisão/Avistamento',
                    ID = var_item.ID
                )
            ),
            Navigate(
                ScreenSucesso,
                ScreenTransition.Fade,
                {var_navigateSucess: ScreenFauna}
            ),
            Navigate(
                ScreenErro,
                ScreenTransition.Fade,
                {var_navigateErro: ScreenFauna}
            )
        ),
        "Presença",
        RemoveIf(
            'AIRPORTNOW - FAUNA RELACIONAMENTO',
            ID_tblPrincipal = var_item.ID And 'Tipo de Registro' = "Presença de fauna"
        );
        RemoveIf(
            'Presença de Fauna',
            ID = var_item.ID
        );
        If(
            IsBlank(
                LookUp(
                    'Presença de Fauna',
                    ID = var_item.ID
                )
            ),
            Navigate(
                ScreenSucesso,
                ScreenTransition.Fade,
                {var_navigateSucess: ScreenFauna}
            ),
            Navigate(
                ScreenErro,
                ScreenTransition.Fade,
                {var_navigateErro: ScreenFauna}
            )
        ),
        "Foco",
        RemoveIf(
            'Formulário de Focos (Atrativos e Vulnerabilidade)',
            ID = var_item.ID
        );
        If(
            IsBlank(
                LookUp(
                    'Formulário de Focos (Atrativos e Vulnerabilidade)',
                    ID = var_item.ID
                )
            ),
            Navigate(
                ScreenSucesso,
                ScreenTransition.Fade,
                {var_navigateSucess: ScreenFauna}
            ),
            Navigate(
                ScreenErro,
                ScreenTransition.Fade,
                {var_navigateErro: ScreenFauna}
            )
        )
    ),
    "Desdobramentos",/////////////////////////////////////////////////////////////////////////////////////
    Remove(
        tbl_desdobramentos,
        var_item
    );
    If(
        IsBlank(
            LookUp(
                tbl_desdobramentos,
                ID = var_item.ID
            )
        ),
        Navigate(
            ScreenSucesso,
            ScreenTransition.Fade,
            {var_navigateSucess: ScreenDesdobramentos}
        ),
        Navigate(
            ScreenErro,
            ScreenTransition.Fade,
            {var_navigateErro: ScreenDesdobramentos}
        )
    )
);
UpdateContext({var_load: false})
